/**
 * Select. Base UI Select behavior, Echo device skin: a
 * molded cap trigger and a floating panel with an accent dot on the selected
 * option. GSAP owns the popup transform/opacity (useGsapPresence). Composes
 * var(--echo-*).
 */
.echo-select__trigger {
  /* One size scale (sm/md/lg): the cap's height is the control height. */
  --ctl-h: var(--echo-control-default);
  --ctl-font: var(--echo-text-md);
  --ctl-px: var(--echo-space-8);
  --ctl-radius: var(--echo-radius-xl);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--echo-space-6);
  /*
   * A floor, not a width: `min-width: 180px` pushed its container open at
   * 320px (the same problem Toast had). `min()` keeps the comfortable width
   * where there is room and gives it up where there isn't.
   */
  min-width: min(180px, 100%);
  height: var(--ctl-h);
  padding: 0 var(--ctl-px);
  border: 0;
  border-radius: var(--ctl-radius);
  cursor: pointer;
  color: var(--echo-text);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--ctl-font);
  /* The HardwareButton neutral cap, stop for stop. */
  background: linear-gradient(
    180deg,
    var(--echo-cap-highlight) 0%,
    var(--echo-cap) 40%,
    var(--echo-cap) 62%,
    var(--echo-cap-shadow) 100%
  );
  box-shadow:
    inset 0 1.5px 0 rgb(255 255 255 / calc(0.42 * var(--echo-gloss, 1))),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1))),
    inset 0 -3px 4px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.5 * var(--echo-shade, 1) * 100%), transparent),
    0 calc(4px + 1px * var(--lift, 0) - 3px * var(--press, 0)) 0 var(--echo-seam),
    0 calc(9px + 5px * var(--lift, 0) - 6px * var(--press, 0)) calc(14px + 10px * var(--lift, 0) - 9px * var(--press, 0))
      color-mix(in oklab, var(--echo-cast-ink, black) calc(0.55 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
  /* useCapPhysics owns the transform: lift, lean, travel onto the seam. */
}
.echo-select__trigger[data-size="sm"] {
  --ctl-h: var(--echo-control-compact);
  --ctl-font: var(--echo-text-sm);
  --ctl-px: var(--echo-space-6);
  --ctl-radius: var(--echo-radius-lg);
  min-width: min(140px, 100%);
}
.echo-select__trigger[data-size="lg"] {
  --ctl-h: var(--echo-control-large);
  --ctl-font: var(--echo-text-lg);
  --ctl-px: var(--echo-space-9);
  --ctl-radius: var(--echo-radius-2xl);
}
.echo-select__trigger:focus-visible {
  /* Drawn only in forced colors, which drops the shadow ring. */
  outline: 2px solid transparent;
  outline-offset: 2px;
  box-shadow: var(
    --echo-shadow-ring,
    0 0 0 2px var(--echo-surface),
    0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow))
  );
}

.echo-select__icon {
  display: inline-flex;
  color: var(--echo-text-dim);
  transition: transform var(--echo-duration-swap) ease;
}
.echo-select__trigger[data-popup-open] .echo-select__icon {
  transform: rotate(180deg);
}

/* Above any dialog it opens from. */
.echo-select__positioner {
  z-index: var(--echo-z-popover, 300);
}

.echo-select__popup {
  /* The flowing highlight is positioned against the panel. */
  position: relative;
  box-sizing: border-box;
  min-width: var(--anchor-width);
  max-height: var(--available-height);
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: var(--echo-space-3);
  border-radius: var(--echo-radius-xl);
  color: var(--echo-text);
  /*
   * The same plastic as the trigger it drops from — cap at the top, settling
   * to the cap's shadow — with the trigger's lit top edge. It used to be the
   * flat page surface, so an open Select read as a molded button with a grey
   * sheet of paper under it.
   */
  background: linear-gradient(180deg, var(--echo-cap) 0%, var(--echo-cap-shadow) 100%);
  box-shadow:
    inset 0 1.5px 0 rgb(255 255 255 / calc(0.28 * var(--echo-gloss, 1))),
    inset 0 0 0 1px color-mix(in oklab, var(--echo-seam) 70%, transparent),
    0 24px 48px -18px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.8 * var(--echo-shade, 1) * 100%), transparent);
  outline: none;
  /* Base UI's origin is the edge that meets the trigger, so the sheet grows
     from the cap it drops out of, on whichever side it opened. */
  transform-origin: var(--transform-origin, top center);
  /* It unrolls out of its trigger: solid quickly, its length overshooting and
     settling. Leaving, it rolls back up, quick and plain. */
  transition:
    opacity var(--echo-duration-swap) ease,
    transform var(--echo-duration-pop) var(--echo-ease-pop);
}
.echo-select__popup[data-ending-style] {
  transition-duration: var(--echo-duration-swap);
  transition-timing-function: ease-in;
}
.echo-select__popup[data-starting-style],
.echo-select__popup[data-ending-style] {
  opacity: 0;
  transform: scale(0.96, 0.4);
}

@media (prefers-reduced-motion: reduce) {
  .echo-select__popup {
    transition-duration: var(--echo-duration-glitch);
    transform: none;
  }
}

.echo-select__item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--echo-space-6);
  padding: var(--echo-space-4) var(--echo-space-6);
  border-radius: var(--echo-radius-md);
  cursor: pointer;
  user-select: none;
  font-size: var(--echo-text-sm);
  color: var(--echo-text-dim);
  /* The highlight marks the current option, for the pointer and the arrow
     keys alike; the browser's own ring on top was a second mark. */
  outline: none;
}
.echo-select__item[data-highlighted] {
  background: color-mix(in oklab, var(--echo-cap-highlight) 55%, transparent);
  color: var(--echo-text);
}
.echo-select__item[data-selected] {
  color: var(--echo-text);
}

/*
 * ONE mark for the chosen item: a check in the text colour. Base UI's
 * ItemIndicator renders a ✔️ emoji when given no children, and this rule used
 * to paint the same element as a glowing accent dot — so the chosen row
 * showed both at once.
 */
.echo-select__indicator {
  display: inline-flex;
  flex: none;
  color: var(--echo-text);
}

.echo-select__indicator svg {
  width: var(--echo-icon-sm, 14px);
  height: var(--echo-icon-sm, 14px);
}

/*
 * Forced colors (Windows High Contrast) drops the recessed well's gradient and
 * shadows, which is its whole edge: without a border an input, and above all
 * an empty one, isn't visible at all. System colors only, so focus still shows.
 */
@media (forced-colors: active) {
  .echo-select__trigger {
    border: var(--echo-border-hairline, 1px) solid ButtonText;
  }
}

/*
 * The flowing highlight (useLiquidHighlight): one cap that travels to the
 * hovered item on a spring. Once it shows, the popup has data-glow and the
 * items drop their own tint.
 */
.echo-select__glow {
  position: absolute;
  z-index: var(--echo-z-base, 0);
  visibility: hidden;
  pointer-events: none;
  will-change: transform, top, height;
}
.echo-select__glow-shape {
  position: absolute;
  inset: 0;
  border-radius: var(--echo-radius-md);
  background: color-mix(in oklab, var(--echo-cap-highlight) 55%, transparent);
}
.echo-select__popup[data-glow] .echo-select__item[data-highlighted] {
  background: transparent;
}
.echo-select__item {
  position: relative;
  z-index: var(--echo-z-raised, 1);
}
@media (forced-colors: active) {
  .echo-select__glow {
    display: none;
  }
  /* The highlight is hidden here, so the current option carries the mark. */
  .echo-select__item[data-highlighted] {
    outline: var(--echo-border-thick, 2px) solid Highlight;
    outline-offset: -2px;
  }
}

"use client";

/**
 * Select. Base UI Select behavior (typeahead,
 * keyboard, a11y) skinned as an Echo device dropdown — a molded cap trigger and
 * a floating panel with an accent dot on the selected option. sound.select on
 * change. The popup fades/scales via CSS (Base UI auto-detects the transition),
 * so no GSAP presence is needed here.
 *
 * NOTE: the package is `@base-ui/react`, NOT `@base-ui-components/react`.
 */
import { Select as BaseSelect } from "@base-ui/react/select";
import { forwardRef, useMemo } from "react";
import type { EchoInterop, EchoPortalContainer } from "echo-ui-core/types";
import { useSoundOptional } from "echo-ui-core/sound";
import { mergeHandlers, mergeRefs, useCapPhysics, useLiquidHighlight } from "echo-ui-core/tactile";
import { useControlSize, type ControlSize } from "../size";
import "./select.css";

export interface SelectOption {
  value: string;
  label: string;
}

interface SelectOwnProps extends EchoInterop {
  options: SelectOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** The greyed text shown until something is chosen. Not a label. */
  placeholder?: string;
  /**
   * Height on the control scale: `sm` 32px, `md` 44px (default), `lg` 60px,
   * the same as a Field or HardwareButton of that size. Defaults to the
   * nearest SizeProvider's size.
   */
  size?: ControlSize;
  /**
   * Where the list mounts. Defaults to <body>. Pass an element inside a
   * scoped theme (`createEchoTheme(seed, { selector })`) and the list wears
   * that theme too — mounted on <body>, it can only read the :root one.
   */
  container?: EchoPortalContainer;
}

/**
 * A control has to have a name: `aria-label`, or
 * `aria-labelledby` pointing at visible text. Leaving both out is a type
 * error, so it gets decided rather than forgotten.
 */
type AccessibleName =
  | { "aria-label": string; "aria-labelledby"?: string }
  | { "aria-labelledby": string; "aria-label"?: string };

export type SelectProps = SelectOwnProps & AccessibleName;

function ChevronDown() {
  return (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M6 9l6 6 6-6" />
    </svg>
  );
}

function CheckIcon() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M3.5 8.5l3 3 6-7" />
    </svg>
  );
}

/**
 * `forwardRef`, not a `ref` prop — see the note on `Field`.
 *
 * The ref lands on the TRIGGER, because that is the focusable element: it is
 * what `shouldFocusError` calls `.focus()` on, and what `onBlur` and `onFocus`
 * fire from. Form participation — `name`, `required`, `readOnly` — belongs to
 * the Root, which owns the hidden input. So the interop set is split by hand
 * here rather than spread wholesale: the two halves go to different elements.
 */
export const Select = forwardRef<HTMLButtonElement, SelectProps>(function Select(
  {
    options,
    size: ownSize,
    value,
    defaultValue,
    onValueChange,
    placeholder = "Select…",
    disabled,
    name,
    required,
    readOnly,
    id,
    autoFocus,
    onBlur,
    onFocus,
    onKeyDown,
    "aria-label": ariaLabel,
    "aria-labelledby": ariaLabelledby,
    container,
    ...rest
  },
  ref,
) {
  const sound = useSoundOptional();
  const size = useControlSize(ownSize);
  // The hovered option is marked by one cap flowing from option to option.
  const glow = useLiquidHighlight();
  // The trigger is the button's neutral cap, so it presses like one.
  const cap = useCapPhysics<HTMLButtonElement>({ tilt: 3 });
  const capRef = cap.ref;
  const triggerRef = useMemo(() => mergeRefs(ref, capRef), [ref, capRef]);

  return (
    <BaseSelect.Root
      items={options}
      value={value}
      defaultValue={defaultValue}
      disabled={disabled}
      name={name}
      required={required}
      readOnly={readOnly}
      onValueChange={(next) => {
        sound?.play("select");
        onValueChange?.(next as string);
      }}
    >
      <BaseSelect.Trigger
        ref={triggerRef}
        /*
         * Spread only when set. The Trigger owns the keys that open the
         * listbox, and an explicit `onKeyDown={undefined}` overrides that
         * rather than leaving it alone.
         */
        {...(id ? { id } : {})}
        {...(autoFocus ? { autoFocus } : {})}
        {...(onFocus ? { onFocus } : {})}
        className="echo-select__trigger"
        data-size={size}
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledby}
        {...rest}
        // The cap's own pointer and key handlers, with the caller's onBlur and
        // onKeyDown run first (the Trigger's own key handling is untouched).
        {...mergeHandlers(cap.handlers, { onBlur, onKeyDown, ...rest })}
      >
        <BaseSelect.Value placeholder={placeholder} />
        <BaseSelect.Icon className="echo-select__icon">
          <ChevronDown />
        </BaseSelect.Icon>
      </BaseSelect.Trigger>
      <BaseSelect.Portal container={container}>
        <BaseSelect.Positioner
          className="echo-select__positioner"
          side="bottom"
          align="start"
          sideOffset={8}
          alignItemWithTrigger={false}
        >
          <BaseSelect.Popup ref={glow.container} className="echo-select__popup">
            <span ref={glow.light} className="echo-select__glow" aria-hidden>
              <span ref={glow.shape} className="echo-select__glow-shape" />
            </span>
            {options.map((option) => (
              <BaseSelect.Item key={option.value} value={option.value} className="echo-select__item">
                <BaseSelect.ItemText>{option.label}</BaseSelect.ItemText>
                {/* Explicit children: with none, Base UI renders a ✔️ emoji. */}
                <BaseSelect.ItemIndicator className="echo-select__indicator">
                  <CheckIcon />
                </BaseSelect.ItemIndicator>
              </BaseSelect.Item>
            ))}
          </BaseSelect.Popup>
        </BaseSelect.Positioner>
      </BaseSelect.Portal>
    </BaseSelect.Root>
  );
});
